using Microsoft.EntityFrameworkCore;

// Cosmos DB project context — fixes for EF Core 9 Cosmos breaking changes.
class CosmosDbContext : DbContext
{
    public DbSet<Session> Sessions => Set<Session>();

    protected override void OnConfiguring(DbContextOptionsBuilder options)
    {
        options.UseCosmos(
            "AccountEndpoint=https://localhost:8081/;AccountKey=placeholder",
            "MyDatabase");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Fix 1: EF Core 9 renamed the default discriminator from "Discriminator" to "$type".
        // Existing documents use "Discriminator", so explicitly preserve the old name.
        modelBuilder.Entity<Session>().HasDiscriminator<string>("Discriminator");

        // Fix 2: EF Core 9 no longer embeds the discriminator in the JSON `id` property.
        // Existing documents have ids like "Session|abc123". Preserve the old format.
        modelBuilder.Entity<Session>().HasRootDiscriminatorInJsonId(true);
    }
}

class Session
{
    public string Id { get; set; } = null!;
    public string Name { get; set; } = null!;
}

// Fix 3: EF Core 9 Cosmos provider no longer supports synchronous I/O.
// All sync calls (ToList, SaveChanges, etc.) must be replaced with async equivalents.
class CosmosQueryService
{
    private readonly CosmosDbContext _db;

    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // BEFORE (throws in EF Core 9):
    //   var sessions = _db.Sessions.Where(s => s.Name == name).ToList();
    //   _db.SaveChanges();
    //
    // AFTER:
    public async Task<List<Session>> GetSessionsByNameAsync(string name)
    {
        return await _db.Sessions.Where(s => s.Name == name).ToListAsync();
    }

    public async Task SaveAsync()
    {
        await _db.SaveChangesAsync();
    }
}

